user_prompt:
你是一个智能助手，专门负责调用各种工具来帮助用户解决问题。你可以根据用户的需求选择一个或多个合适的工具并正确调用它们。
 在<tools></tools>标签中为你提供了详细的工具列表。

 <tools>
 {"type": "function", "function": {"name": "open_goods_page", "description": "通过商品名称找到并打开其详情页面，可以指定子页面，例如评论、规格、参数、详情等", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "search_info_slot": {"type": "string", "description": "需要搜索并打开的商品详情页面的商品的具体名称"}, "page_type": {"type": "string", "description": "指定的详情页面具体子页面名称，例如评论、规格、参数、详情等", "enum": ["无", "评论", "规格", "参数", "详情"]}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "open_special_page", "description": "打开特殊页面，例如活动页面", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "page_type": {"type": "string", "description": "指定的页面名称"}}, "required": ["app", "page_type"]}}}
 {"type": "function", "function": {"name": "open_stores_page", "description": "通过店铺名称找到并打开店铺的内容页面，可以在其中进行店铺内搜索或打开类别子页面", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "store_name_slot": {"type": "string", "description": "需要打开的店铺名称"}, "search_info_slot": {"type": "string", "description": "进行店铺内搜索的具体内容"}, "category_slot": {"type": "string", "description": "指定的店铺类别子页面名称"}}, "required": ["app", "store_name_slot"]}}}
 {"type": "function", "function": {"name": "ask_human", "description": "使用这个工具向用户发起提问用来补充信息，当发现调用的工具缺少必填信息时非常有用。", "parameters": {"type": "object", "properties": {"inquire": {"type": "string", "description": "想要向用户提问的问题"}}, "required": ["inquire"]}}}
 {"type": "function", "function": {"name": "get_reference_info", "description": "获取关于指代信息的详细内容，当发现用户输入的内容包含指代实体时非常有用。", "parameters": {"type": "object", "properties": {"entity": {"type": "string", "description": "用户输入内容中的指代实体，如'我家','公司','爸爸','妈妈'等"}}, "required": ["entity"]}}}
 {"type": "function", "function": {"name": "not_support", "description": "针对无正确可用工具场景，提示用户当前功能不支持", "parameters": {}}}
 </tools>

 针对用户给你的每个问题或任务，你必须输出DSL格式的工具调用结果，示例如下：
 [['1', '工具名称1(参数1=参数值1, 参数2=参数值2)'], ['2', '工具名称2(参数1=参数值1)']]

 用户的问题或任务是:"在京东中打开‘小熊电器旗舰店’，搜索迷你电饭煲"

